// The app: the IceBase config (generated by `icebase gen dart`) plus the environment to run.
// Each service runs in the mode config.environments[env] gives it.

import 'errors.dart';
import 'schema.dart';

const services = ['firestore', 'auth', 'database', 'storage', 'functions', 'hosting'];

/// Which sign-in methods IceBase takes over from Firebase (config.auth.custom).
class CustomAuthInfo {
  final bool email;
  final bool phone;
  final bool google;

  /// approval | link | code
  final String emailSignIn;

  /// Where the custom-auth endpoint is; null = the default for the mode.
  final String? endpoint;
  final String storePath;
  const CustomAuthInfo({this.email = false, this.phone = false, this.google = false, this.emailSignIn = 'link', this.endpoint, this.storePath = '_icebase/auth'});
}

/// What `icebase gen dart` writes from icebase.config.ts.
class IceBaseConfig {
  final String name;
  final String projectId;
  final Schema schema;

  /// env → service → mode (firebase | emulator | vm).
  final Map<String, Map<String, String>> environments;
  final String emulatorHost;
  final int emulatorPort;
  final String functionsRegion;
  final String? storageBucket;
  final String? databaseUrl;
  final CustomAuthInfo? customAuth;

  const IceBaseConfig({
    required this.name,
    required this.projectId,
    required this.schema,
    required this.environments,
    this.emulatorHost = '127.0.0.1',
    this.emulatorPort = 4400,
    this.functionsRegion = 'us-central1',
    this.storageBucket,
    this.databaseUrl,
    this.customAuth,
  });
}

/// A backend for the services of one app in one mode (registered by `icebase_flutter` for
/// firebase mode; the emulator drivers ship with this package).
abstract interface class DriverFactory {
  Object create(IceBaseApp app, String service);
}

class IceBaseApp {
  final String name;
  final String env;
  final IceBaseConfig config;
  final Map<String, String> modes;

  /// Where the IceBase emulator server is ('http://127.0.0.1:4400').
  final String emulatorOrigin;
  final Map<String, Object> _services = {};
  final List<Future<void> Function()> _onDelete = [];
  bool _deleted = false;

  /// @nodoc the signed-in user's ID token, set by the auth service (emulator drivers send it).
  Future<String?> Function()? idToken;

  static final Map<String, IceBaseApp> _apps = {};
  static final Map<String, DriverFactory> _factories = {};

  IceBaseApp._(this.name, this.env, this.config, this.modes, this.emulatorOrigin);

  /// IceBaseApp.initialize(config, 'local') — like Firebase.initializeApp, with the IceBase
  /// config and the environment.
  static IceBaseApp initialize(IceBaseConfig config, String env, {String name = '[DEFAULT]', String? emulatorOrigin}) {
    final existing = _apps[name];
    if (existing != null) {
      if (identical(existing.config, config) && existing.env == env) return existing;
      throw IceBaseException('already-exists', "IceBase app '$name' already exists with a different config or environment", reason: 'config');
    }
    final e = config.environments[env];
    if (e == null) throw IceBaseException('failed-precondition', "environment '$env' is not in the config (${config.environments.keys.join(', ')})", reason: 'config');
    final modes = {for (final s in services) s: e[s] ?? e['*'] ?? 'firebase'};
    final app = IceBaseApp._(name, env, config, modes, emulatorOrigin ?? 'http://${config.emulatorHost}:${config.emulatorPort}');
    return _apps[name] = app;
  }

  static IceBaseApp instance([String name = '[DEFAULT]']) {
    final a = _apps[name];
    if (a == null) throw IceBaseException('not-found', "No IceBase app '$name' — call IceBaseApp.initialize(config, env) first", reason: 'config');
    return a;
  }

  /// Register the drivers of a mode ('firebase' from icebase_flutter).
  static void registerDrivers(String mode, DriverFactory factory) => _factories[mode] = factory;

  /// @nodoc the driver for one service (created once).
  T driver<T extends Object>(String service, T Function()? emulator) {
    if (_deleted) throw IceBaseException('failed-precondition', "IceBase app '$name' was deleted", reason: 'config');
    return _services.putIfAbsent(service, () {
      final mode = modes[service]!;
      if (mode == 'emulator' && emulator != null) return emulator();
      final f = _factories[mode];
      if (f == null) {
        throw IceBaseException('unimplemented', mode == 'firebase' ? '$service in firebase mode needs icebase_flutter (IceBaseFlutter.register())' : '$service in $mode mode is not available',
            reason: 'mode');
      }
      return f.create(this, service);
    }) as T;
  }

  /// @nodoc a per-app singleton (the service objects).
  T single<T extends Object>(String key, T Function() make) => _services.putIfAbsent(key, make) as T;

  /// @nodoc teardown run by delete().
  void onDelete(Future<void> Function() fn) => _onDelete.add(fn);

  Future<void> delete() async {
    if (_deleted) return;
    _deleted = true;
    _apps.remove(name);
    for (final fn in _onDelete.reversed) {
      await fn();
    }
    _services.clear();
  }
}
